export default {"html":"<p data-line=\"0\" class=\"code-line\">I keep saying Signal-Based Reactivity is the best in Angular, but it does not mix well with lifecycle hacks. Ionic especially ties screen rendering to lifecycle hooks (<code>ionViewWillEnter</code>, etc.), and ignoring render timing leads to problems like this:</p>\n<ul data-line=\"2\" class=\"code-line\">\n<li data-line=\"2\" class=\"code-line\">Rendering a lot of data before a push transition</li>\n<li data-line=\"3\" class=\"code-line\">The transition animation starts</li>\n<li data-line=\"4\" class=\"code-line\">Memory leaks and the app crashes</li>\n</ul>\n<p data-line=\"6\" class=\"code-line\">The docs cover this.</p>\n<blockquote data-line=\"8\" class=\"code-line\">\n<p data-line=\"8\" class=\"code-line\">However, fetching data during an animation may trigger a large number of DOM operations. This can result in choppy animation.<br>\n<a href=\"https://ionicframework.jp/docs/angular/lifecycle/\" target=\"_blank\" rel=\"noopener noreferrer\">https://ionicframework.jp/docs/angular/lifecycle/</a></p>\n</blockquote>\n<p data-line=\"11\" class=\"code-line\">The simple fix is not to start rendering in <code>ngOnInit</code> or <code>ionViewWillEnter</code>, but to start in <code>ionViewDidEnter</code>. In performance-conscious classes, what runs on each lifecycle hook still matters—and that has not changed.</p>\n<p data-line=\"13\" class=\"code-line\">What about Signal-based development? Right—<code>computed</code>, <code>effect</code>, and <code>httpResource</code> all react when Signals they depend on change. I can also map lifecycle onto Signals by updating them in page lifecycle hooks:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"15\"><span class=\"line\"><span style=\"color:#E1E4E8\">readonly didViewEnter </span><span style=\"color:#F97583\">=</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#79B8FF\">boolean</span><span style=\"color:#E1E4E8\">&gt;(</span><span style=\"color:#79B8FF\">false</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#B392F0\">ionViewWillEnter</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">  this</span><span style=\"color:#E1E4E8\">.didViewEnter.</span><span style=\"color:#B392F0\">set</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">false</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#B392F0\">ionViewDidEnter</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">  this</span><span style=\"color:#E1E4E8\">.didViewEnter.</span><span style=\"color:#B392F0\">set</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">true</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><aside class=\"msg message\"><span class=\"msg-symbol\">!</span><div class=\"msg-content\"><p data-line=\"28\" class=\"code-line\">Lifecycle hooks fire only on page components (the component specified in routing). The same applies to <code>createDidEnter</code> below—do not use this in child components. In Ionic Angular naming, that means components whose class name includes <code>Page</code>.</p>\n</div></aside>\n<p data-line=\"31\" class=\"code-line\">But \"am I supposed to write this on every page component and maintain it? Seriously?!\"—that is how I felt. So let me look for a simpler way to replace Ionic lifecycle with Signals.</p>\n<p data-line=\"33\" class=\"code-line\">First, define a helper like this:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"35\"><span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#B392F0\"> createDidEnter</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> &lt;</span><span style=\"color:#B392F0\">T</span><span style=\"color:#F97583\"> =</span><span style=\"color:#79B8FF\"> any</span><span style=\"color:#E1E4E8\">&gt;(</span><span style=\"color:#FFAB70\">el</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> ElementRef</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  return</span><span style=\"color:#F97583\"> new</span><span style=\"color:#B392F0\"> Observable</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">observer</span><span style=\"color:#F97583\"> =&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    const</span><span style=\"color:#B392F0\"> willEnter</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> observer.</span><span style=\"color:#B392F0\">next</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">false</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    const</span><span style=\"color:#B392F0\"> didEnter</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> observer.</span><span style=\"color:#B392F0\">next</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">true</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    </span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    el.nativeElement.</span><span style=\"color:#B392F0\">addEventListener</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'ionViewWillEnter'</span><span style=\"color:#E1E4E8\">,willEnter);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    el.nativeElement.</span><span style=\"color:#B392F0\">addEventListener</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'ionViewDidEnter'</span><span style=\"color:#E1E4E8\">, didEnter);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#E1E4E8\"> () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      el.nativeElement.</span><span style=\"color:#B392F0\">removeEventListener</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'ionViewWillEnter'</span><span style=\"color:#E1E4E8\">,willEnter);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      el.nativeElement.</span><span style=\"color:#B392F0\">removeEventListener</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'ionViewDidEnter'</span><span style=\"color:#E1E4E8\">, didEnter);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }).</span><span style=\"color:#B392F0\">pipe</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">startWith</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">false</span><span style=\"color:#E1E4E8\">));</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"52\" class=\"code-line\">Ionic lifecycle hooks also fire as event listeners on the page component (unlike Angular lifecycle). So I build an Observable that emits <code>false</code> on <code>ionViewWillEnter</code> and <code>true</code> on <code>ionViewDidEnter</code>, then convert it to a Signal on the page:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"54\"><span class=\"line\"><span style=\"color:#E1E4E8\">readonly el </span><span style=\"color:#F97583\">=</span><span style=\"color:#B392F0\"> inject</span><span style=\"color:#E1E4E8\">(ElementRef);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">readonly didEnter </span><span style=\"color:#F97583\">=</span><span style=\"color:#B392F0\"> toSignal</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">createDidEnter</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.el));</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"59\" class=\"code-line\">Now I have a <code>didEnter</code> property driven by Ionic lifecycle. I can write like this:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"61\"><span class=\"line\"><span style=\"color:#E1E4E8\">readonly data </span><span style=\"color:#F97583\">=</span><span style=\"color:#B392F0\"> httpResource</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">data</span><span style=\"color:#E1E4E8\">[]&gt;(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    const</span><span style=\"color:#79B8FF\"> params</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> new</span><span style=\"color:#B392F0\"> HttpParams</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">append</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'search'</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#B392F0\">searchWord</span><span style=\"color:#E1E4E8\">());</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#F97583\"> !</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">didEnter</span><span style=\"color:#E1E4E8\">() </span><span style=\"color:#F97583\">?</span><span style=\"color:#79B8FF\"> undefined</span><span style=\"color:#F97583\"> :</span><span style=\"color:#E1E4E8\"> environment.api </span><span style=\"color:#F97583\">+</span><span style=\"color:#9ECBFF\"> 'manager/movies?'</span><span style=\"color:#F97583\"> +</span><span style=\"color:#E1E4E8\"> params.</span><span style=\"color:#B392F0\">toString</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"68\" class=\"code-line\">When <code>isReady</code> is false, an empty value is returned; when true, the request runs. Signal-based Ionic development gets even faster from here!</p>\n","headings":[]} as const;
